const edicionId = $('Update a row').first().json.edicion_id;
let fuente = $('Get fuente').first().json;
if (Array.isArray(fuente)) fuente = fuente[0];
let portada = $('Get portada').first().json;
if (Array.isArray(portada)) portada = portada[0];
const portadaUrl = (portada && portada.imagen_url) ? portada.imagen_url
  : (fuente && fuente.portada_url) ? fuente.portada_url : null;

const tituloEdicion = (fuente && fuente.titulo) ? fuente.titulo : "";
const fechaSlug = (fuente && fuente.fecha) ? fuente.fecha : ""; // dd-mm-yyyy
const parts = fechaSlug.split("-").map(Number);
const dd = parts[0], mm = parts[1], yyyy = parts[2];
let expediente = "", anexo = "";
if (dd && mm && yyyy) {
  const doy = Math.round((Date.UTC(yyyy, mm-1, dd) - Date.UTC(yyyy,0,0)) / 86400000);
  const ddd = String(doy).padStart(3,"0");
  expediente = yyyy + "_" + ddd + "-AR-01";
  anexo = expediente + "-S";
}
function pulsoOf(n){
  const p = Array.isArray(n.el_pulso_noticia) ? n.el_pulso_noticia[0] : n.el_pulso_noticia;
  return { texto:(p&&p.texto_resumen)||"", pos:(p&&p.pct_positiva)||0, neg:(p&&p.pct_negativa)||0, inc:(p&&p.pct_incierta)||0 };
}
const noticias = ((fuente && fuente.noticias) || []).slice().sort((a,b)=>a.orden-b.orden);
const n1 = noticias[0] || { titulo:"", cuerpo:"" };
const p1 = pulsoOf(n1);
const otrasTitulos = noticias.slice(1,5).map(n=>n.titulo);

const prompt = [
 "Sos editor de La Puta Política, medio político argentino para jóvenes (serio pero con carácter).",
 "Generá contenido para un carrusel de Instagram a partir de las noticias del día.",
 "",
 "NOTICIA PRINCIPAL:",
 "Título: " + n1.titulo,
 "Texto: " + (n1.cuerpo || ""),
 "Lectura de la comunidad (El Pulso): " + p1.texto,
 "",
 "OTRAS NOTICIAS (títulos, en orden):",
 ...otrasTitulos.map((t,i)=>(i+1) + ". " + t),
 "",
 'Devolvé SOLO un JSON con esta forma exacta:',
 '{"bullets_noticia":["..x5.."],"bullets_pulso":["..x5.."],"titulares":["..x4.."]}',
 "- bullets_noticia: 5 viñetas cortas (máx ~80 caracteres c/u) que resuman la NOTICIA PRINCIPAL. Declarativas, sin emojis, sin comillas.",
 "- bullets_pulso: 5 viñetas cortas que sinteticen la LECTURA DE LA COMUNIDAD de la noticia principal.",
 "- titulares: 4 titulares ULTRA cortos, uno por cada OTRA noticia en el MISMO orden. REGLAS DURAS: cada titular debe entrar en máximo 2 renglones de máximo 12 caracteres cada uno (los espacios cuentan); ninguna palabra puede superar 12 caracteres; no partir palabras. Apuntá a 2-3 palabras cortas."
].join("\n");

return [{ json: {
  edicion_id: edicionId,
  titulo_edicion: tituloEdicion,
  fecha: fechaSlug,
  expediente, anexo,
  portada_url: portadaUrl,
  n1_titulo: n1.titulo,
  votos: { positiva: p1.pos, negativa: p1.neg, incierta: p1.inc },
  otras_titulos: otrasTitulos,
  groq_prompt: prompt
}}];

const src = $('Preparar fuente').first().json;
let content = "";
try { content = $json.choices[0].message.content; } catch (e) { content = ""; }
let parsed = {};
try { parsed = JSON.parse(content); } catch (e) { parsed = {}; }

const bn = Array.isArray(parsed.bullets_noticia) ? parsed.bullets_noticia.slice(0,5) : [];
const bp = Array.isArray(parsed.bullets_pulso) ? parsed.bullets_pulso.slice(0,5) : [];
const tit = Array.isArray(parsed.titulares) ? parsed.titulares.slice(0,4) : [];

function fits(h){
  if (typeof h !== "string" || !h.trim()) return false;
  const words = h.trim().split(/\s+/);
  if (words.some(w => w.length > 12)) return false;
  const lines = []; let cur = "";
  for (const w of words){
    const cand = cur ? cur + " " + w : w;
    if (cand.length <= 12) cur = cand; else { lines.push(cur); cur = w; }
  }
  if (cur) lines.push(cur);
  return lines.length <= 2;
}

const titulares = (src.otras_titulos || []).map((orig, i) => {
  const t = tit[i] || "";
  return { texto: t, ok: fits(t), fuente: orig };
});

const fecha = src.fecha;
const slides = [
  { orden:1, texto: src.titulo_edicion, imagen_url: src.portada_url,
    payload: { tipo:"tapa", titulo_edicion: src.titulo_edicion, fecha } },
  { orden:2, texto: bn.join("\n"), imagen_url: null,
    payload: { tipo:"noticia", expediente: src.expediente, titulo: src.n1_titulo, bullets: bn, fecha } },
  { orden:3, texto: bp.join("\n"), imagen_url: null,
    payload: { tipo:"pulso", anexo: src.anexo, bullets: bp, votos: src.votos, fecha } },
  { orden:4, texto: titulares.map(t=>t.texto).join("\n"), imagen_url: null,
    payload: { tipo:"titulares", titulares, fecha } }
];
return [{ json: { edicion_id: src.edicion_id, slides } }];

const r = $input.all()[0].json;
const pubId = Array.isArray(r) ? r[0].id : (r.id || (r[0] && r[0].id));
const data = $('Armar slides').first().json;
const rows = data.slides.map(s => ({
  publicacion_instagram_id: pubId,
  orden: s.orden,
  texto: s.texto,
  imagen_url: s.imagen_url,
  payload: s.payload
}));
return [{ json: { rows } }];
